# Reading the pdf file
class PDFReader:
    def __init__(self):
        pass
    def read_pdf(self,file_path:str) -> List[Document]:
        "Funtion to read the pdf file and return the list of documents."

        all_docs = []   # Storing all the documents in a list.
        pdf_path = Path(file_path) # Getting all the pdf files in the given path.

        try:
            loader = PyPDFLoader(str(pdf_path))  
            docs = loader.load()

            for doc in docs:
                doc.metadata['source'] = str(pdf_path.name)
                doc.metadata['file_type'] = 'pdf'
                    
            all_docs.extend(docs)    
        except Exception as e:
            print(f"Error reading the pdf file: {e}")

        return all_docs

# Converting the documents into chunks of text.
class TextSplitter:
    def __init__(self,chunk_size:int=500,chunk_overlap:int=100,loader: Any = None):
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.loader = loader

    def split_text(self,file_path:str,file_hash:str):
        "Function to split the text into chunks of specified size and overlap."
        text_splitter = RecursiveCharacterTextSplitter(
            chunk_size=self.chunk_size,
            chunk_overlap = self.chunk_overlap,
            length_function = len ,
            separators=["\n\n",'\n'," ",""]
        )

        "Loading the documents using the PDFReader class and splitting the text into chunks."
        documents = self.loader.read_pdf(file_path)
        chunks = text_splitter.split_documents(documents)

        for doc in chunks:
                doc.metadata['file_hash'] = file_hash  # attach to chunks not pages

        print(f'Split {len(documents)} documents  into {len(chunks)} chunks')

        return chunks
    
# Converting the chunks into embeddings
class EmbeddingsGenerator:
    def __init__(self,model_name:str='sentence-transformers/all-MiniLM-L6-v2'):
        self.model_name = model_name
        self.model = HuggingFaceEmbeddings(model_name=self.model_name)
    

# Store the embeddings into a vector store and retrieveing the documents
class VectorStore:

    def __init__(self, text_splitter, embeddings,
                 index_dir="vector_store"):
        self.text_splitter = text_splitter
        self.embeddings = embeddings
        self.index_dir = index_dir
        self.meta_file = os.path.join(index_dir, "metadata.json")
        self.vector_store = None

        os.makedirs(index_dir, exist_ok=True)

    @staticmethod
    def _file_hash(file_path):
        sha = hashlib.sha256()

        with open(file_path, "rb") as f:
            while chunk := f.read(8192):
                sha.update(chunk)

        return sha.hexdigest()

    def add_documents(self, file_path):

        new_hash = self._file_hash(file_path)

        # ----------------------------
        # Load metadata
        # ----------------------------
        metadata = {}

        if os.path.exists(self.meta_file):
            with open(self.meta_file, "r") as f:
                metadata = json.load(f)

        # ----------------------------
        # Already indexed?
        # ----------------------------
        if new_hash in metadata:

            print(f"'{os.path.basename(file_path)}' is already stored.")
            print("Loading existing FAISS index...")

            self.vector_store = FAISS.load_local(
                self.index_dir,
                self.embeddings,
                allow_dangerous_deserialization=True,
            )

            return

        print(f"Adding new PDF: {os.path.basename(file_path)}")

        chunks = self.text_splitter.split_text(file_path, new_hash)

        # ----------------------------
        # Existing index?
        # ----------------------------
        if os.path.exists(os.path.join(self.index_dir, "index.faiss")):

            self.vector_store = FAISS.load_local(
                self.index_dir,
                self.embeddings,
                allow_dangerous_deserialization=True,
            )

            self.vector_store.add_documents(chunks)

        else:

            self.vector_store = FAISS.from_documents(
                chunks,
                self.embeddings
            )

        self.vector_store.save_local(self.index_dir)

        # Store hash instead of file path
        metadata[new_hash] = {
            "file_name": os.path.basename(file_path)
        }

        with open(self.meta_file, "w") as f:
            json.dump(metadata, f, indent=4)

        print(f"Added {len(chunks)} chunks.")

    def get_retriever(self, k=5):

        if self.vector_store is None:

            self.vector_store = FAISS.load_local(
                self.index_dir,
                self.embeddings,
                allow_dangerous_deserialization=True,
            )

        retriever = self.vector_store.as_retriever(
            search_type="similarity_score_threshold",
            search_kwargs={"k": k,"score_threshold":0.2}
        )

        return retriever
    
