class State(TypedDict):
    question : str

    retrieval_query : str
    rewrite_tries : int

    need_retrieval : bool                 # Decides if retrieval is needed or not.
    docs : List[Document]                 # Storing the documents that are retrieved from the vector store.
    relevant_docs : List[Document]       # Storing the only relevant documents.

    context : str                         # adding the all the relevant docs into the context.
    answer : str                          # LLM generated answer.

    # Post generation Verification
    issup : Literal['fully_supported','partially_supported','no_support']  # Whether the answer is supported by the retrieved documents or not.
    evidence : List[str]                            # If the answer is supported or not supported then what is the evidence for that.

    retries : int                             # Number of retries for the question.

    isuse : Literal['useful','not_useful']    # Whether the generated answer is useful or not.
    reason : str                              # If the answer is not useful then what is the reason for that.


