# Step 1: Schema
class RetrievalDecision(BaseModel):
    should_retrieve: bool = Field(
        ...,
        description="True if external documents are needed to answer reliably, else False."
    )

# step 2:  decide retrievalprompt
decide_retrieval_prompt = ChatPromptTemplate.from_messages([
    (
        "system",
        """
    You are a retrieval router for a Retrieval-Augmented Generation (RAG) system.

    Your job is to decide whether the user's question requires searching the uploaded documents.

    Return ONLY valid JSON.

    Schema:

    {{
        "should_retrieve": true | false
    }}

    Decision Rules

    Return "should_retrieve": true ONLY if the answer is likely to exist in the uploaded documents.

    Examples include:
    - Questions about uploaded reports, PDFs, manuals, policies, contracts, research papers, books, budgets, speeches, or company documents.
    - Questions asking about specific content, facts, people, numbers, dates, tables, or sections contained in those documents.
    - Questions that require quoting or extracting information from the uploaded documents.

    Return "should_retrieve": false for questions that can be answered using general knowledge, including:

    - Famous people
    - Definitions
    - Programming
    - Mathematics
    - Science
    - History
    - Geography
    - Common facts
    - General explanations
    - General reasoning
    - Everyday knowledge

    Examples

    Question:
    Who is APJ Abdul Kalam?
    Output:
    {{"should_retrieve": false}}

    Question:
    What is Machine Learning?
    Output:
    {{"should_retrieve": false}}

    Question:
    Explain Python decorators.
    Output:
    {{"should_retrieve": false}}

    Question:
    What is the capital of Japan?
    Output:
    {{"should_retrieve": false}}

    Question:
    Who presented Budget 2026-2027 according to the uploaded Budget document?
    Output:
    {{"should_retrieve": true}}

    Question:
    What is Biopharma SHAKTI mentioned in the uploaded Budget speech?
    Output:
    {{"should_retrieve": true}}

    Question:
    Who asked why India cannot become a developed nation before 2020 in the uploaded APJ Abdul Kalam speech?
    Output:
    {{"should_retrieve": true}}

    Question:
    Summarize Chapter 5 of the uploaded PDF.
    Output:
    {{"should_retrieve": true}}

    If the question explicitly refers to the uploaded document, PDF, report, speech, manual, policy, budget, or asks about information likely contained in them, return true.

    Otherwise, return false.
    """
        ),
        (
            "human",
            "Question:\n{question}"
        ),
])

# step 3 : Clean output parser
def clean_json_output(text: str) -> str:
    text = re.sub(r"```json|```", "", text).strip()
    text = text.replace("'", '"')
    return text

parser = JsonOutputParser(pydantic_object=RetrievalDecision)

# Defining the chain
should_retrieve_chain = (
    decide_retrieval_prompt
    | llm
    | RunnableLambda(lambda x: clean_json_output(x.content)) # Clean the output to ensure it's valid JSON
    | parser
)

# step 5: Get the answer
def decide_retrieval(state:State):
    decision = should_retrieve_chain.invoke({'question': state['question']})
    return {
        'need_retrieval': decision['should_retrieve']
    }


