from langchain_core.output_parsers import PydanticOutputParser

class RelevanceDecision(BaseModel):
    is_relevant: bool = Field(
        ...,
        description="True if the document helps answer the question, else False."
    )

is_relevant_prompt = ChatPromptTemplate.from_messages([
        ('system',
            "You are judging document relevance.\n"
            "Return JSON that matches this schema:\n"
            '{{"is_relevant": true or false}}\n\n'
            "A document is relevant if it contains information useful for answering the question."
        ),
        ('human','Question:\n{question}\n\nDocument:\n{documents}')
])

def clean_json_relevance(text:str) -> str:
    text = re.sub(r"```json|```", "", text).strip()
    text = text.replace("'", '"')
    return text

relevant_parser = PydanticOutputParser(pydantic_object=RelevanceDecision)

relevant_chain = (
    is_relevant_prompt
    | llm
    | RunnableLambda(lambda x:clean_json_relevance(x.content))
    | relevant_parser
)

def is_relevant(state:State):
    relevant_docs : List[Document] = []

    for doc in state['docs']:
        decision : RelevanceDecision = relevant_chain.invoke({
            'question':state['question'],
            'documents':doc.page_content
        })

        if decision.is_relevant:
            relevant_docs.append(doc)

    return {
        'relevant_docs' : relevant_docs
    }

