class IsUSEDecision(BaseModel):
     isuse : Literal['useful','not_useful']
     reason : str = Field(...,description='short reason in 1 line.')

isuse_prompt = ChatPromptTemplate.from_messages([
    (
    "system",
    """
    You are an evaluator that determines whether the ANSWER directly answers the QUESTION.

    Your ONLY task is to judge answer usefulness.

    IMPORTANT:
    - Do NOT check factual correctness.
    - Do NOT check whether the answer is supported by retrieved documents.
    - Do NOT use outside knowledge.
    - Judge ONLY whether the answer satisfies the user's question.

    Return ONLY valid JSON.

    Schema:

    {{
    "isuse":"useful" | "not_useful",
    "reason":"one short sentence"
    }}

    Evaluation Rules

    Return "useful" if the answer:

    • directly answers the user's question.
    • identifies the requested person, organization, policy, strategy, place, date, number or fact.
    • explains the requested concept even if briefly.
    • provides the requested information without unnecessary detail.
    • is short but complete.

    Return "not_useful" only if:

    • it does not answer the question.
    • it is unrelated.
    • it is only generic background.
    • it is too vague to answer the question.
    • it says "I don't know".
    • it says "No relevant documents found."

    Do NOT require the answer to exactly match the wording of the question.

    Examples

    Question:
    Who presented the Budget?

    Answer:
    Nirmala Sitharaman

    Output:
    {{
    "isuse":"useful",
    "reason":"The requested person is identified."
    }}

    Question:
    What is Biopharma SHAKTI?

    Answer:
    Biopharma SHAKTI is a strategy proposed to develop India as a global Biopharma manufacturing hub.

    Output:
    {{
    "isuse":"useful",
    "reason":"The requested strategy is explained."
    }}

    Question:
    When did the meeting happen?

    Answer:
    22 May 2006

    Output:
    {{
    "isuse":"useful",
    "reason":"The requested date is provided."
    }}

    Question:
    What is the refund policy?

    Answer:
    No relevant documents found.

    Output:
    {{
    "isuse":"not_useful",
    "reason":"No answer was provided."
    }}

    Question:
    Who asked the question?

    Answer:
    The passage discusses India's development.

    Output:
    {{
    "isuse":"not_useful",
    "reason":"The question is not answered."
    }}
    """
    ),
    (
    "human",
    """
    Question:
    {question}

    Answer:
    {answer}
    """
    )
    ])

def clean_json_isuse(text:str) -> str:
    text = re.sub(r"```json|```", "", text).strip()
    return text

isuse_parser = PydanticOutputParser(pydantic_object=IsUSEDecision)

isuse_chain = (
    isuse_prompt
    | llm
    | RunnableLambda(lambda x:clean_json_isuse(x.content))
    | isuse_parser
)

def is_use(state:State):
    decision : IsUSEDecision = isuse_chain.invoke({
        'question':state['question'],
        'answer':state.get('answer','')
    })

    return {'isuse':decision.isuse,'reason':decision.reason}

def route_after_isuse(state:State) -> Literal['END','rewrite_question','no_answer_found']:
    if state.get('isuse') == 'useful':
        return 'END'

    if state.get('rewrite_tries',0) < 3:
        return 'rewrite_question'

    return 'no_answer_found'

class RewriteDecision(BaseModel):
     retrieval_query : str = Field(
         ...,
         description='Rewritten query optimized for vector retrieval against internal company PDFs.'
     )

rewrite_for_retrieval_prompt = ChatPromptTemplate.from_messages([
    ('system',
     "Rewrite the user's QUESTION into a query optimized for the vector retrieval over INTERNAL company PDFS.\n\n"
     "Rules:\n"
     "- Keep it short (6-16 words).\n"
     "- Preserve key entities (e.g., NexAI ,plan names).\n"
     "- Add 2-5 high-signal keywords that likely apper in the policy / pricing docs.\n"
     "- Remove filter words\n"
     "- Do NOt answer the question\n"
     "- Output JSON with keys: retrieval_query\n\n"
     "Examples:\n"
     "Q: 'Do NexAI plans include a free trial?'\n"
     '-> {{"retrieval_query":"NexaAi free trial duration trial period plans"}}\n\n'
     "Q: 'What is NexaAI refund policy?'\n"
     '-> {{"retrieval_query":"NexaAi refund policy cancellation refund timeline charges"}}'
     ),
    (
        'human',
        'QUESTION:\n{question}\n\n'
        'Previous retrieval query:\n{retrieval_query}\n\n'
        'Answer (if any):\n{answer}'
    )
])

def clean_json_rewrite(text: str):
    text = re.sub(r"```json|```", "", text).strip()
    return text

rewrite_parser = PydanticOutputParser(pydantic_object=RewriteDecision)

rewrite_chain = (
    rewrite_for_retrieval_prompt
    | llm
    | RunnableLambda(lambda x:clean_json_rewrite(x.content))
    | rewrite_parser
)

def rewrite_question(state:State):
    decision : RewriteDecision = rewrite_chain.invoke(
        {
            'question': state['question'],
            'retrieval_query': state.get('retrieval_query',''),
            'answer':state.get('answer','')
        }
    )

    return {
        'retrieval_query' : decision.retrieval_query,
        'rewrite_tries': state.get('rewrite_tries',0)+1,
    }

# Creating our graph 
g = StateGraph(State)

#Nodes 
g.add_node('decide_retrieval',decide_retrieval)
g.add_node('generate_direct',generate_direct)
g.add_node('retrieve',retrieve)
g.add_node('is_relevant',is_relevant)
g.add_node('generate_from_context',generate_from_context)
g.add_node('no_answer_found',no_answer_found)
g.add_node('is_sup',is_sup)
g.add_node('is_use',is_use)
g.add_node('rewrite_question',rewrite_question)
g.add_node('accept_answer',accept_answer)
g.add_node('revise_answer',revise_answer)

#Starting the node
g.add_edge(START,'decide_retrieval')

g.add_conditional_edges(
    'decide_retrieval',
    route_after_decide,
    {
        'generate_direct':'generate_direct',
        'retrieve':'retrieve'
    }
)

g.add_edge('generate_direct',END)
g.add_edge('retrieve','is_relevant')

g.add_conditional_edges(
    'is_relevant',
    route_after_relevance,
    {
        'generate_from_context':'generate_from_context',
        "rewrite_question":"rewrite_question",
        'no_answer_found':'no_answer_found'
    }
)

g.add_edge('generate_from_context','is_sup')
g.add_edge('no_answer_found',END)

g.add_conditional_edges(
    'is_sup',
    route_after_issup,
    {
        'accept_answer':'accept_answer',
        'revise_answer':'revise_answer',
    }
)

g.add_edge('revise_answer','is_sup') 

g.add_edge('accept_answer','is_use')



g.add_conditional_edges(
    "is_use",
    route_after_isuse,
    {
        "END": END,
        'rewrite_question':'rewrite_question',
        "no_answer_found": "no_answer_found"
    }
)

# rewrite -> retrieve -> relevance -> ....
g.add_edge('rewrite_question','retrieve')


